import random
import math

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def generate_boolean_circuit(depth, size):
        if depth == 0:
            return [random.choice([0, 1])]
        else:
            inputs = generate_boolean_circuit(depth - 1, size // 2)
            outputs = []
            for i in range(size // 2):
                a, b = random.choice(inputs), random.choice(inputs)
                if random.choice([True, False]):
                    outputs.append(a & b)
                else:
                    outputs.append(a | b)
            return outputs

    def compute_minimal_rank(circuit):
        n = len(circuit)
        rank = 0
        for i in range(n):
            if circuit[i] == 1:
                rank += 1
        return rank

    D_values = [5, 10, 15, 20, 30, 40]
    results = []

    for D in D_values:
        n = random.randint(1, min(40, 2**D))
        circuit = generate_boolean_circuit(D, n)
        rank = compute_minimal_rank(circuit)
        results.append(rank)

    avg_rank = sum(results) / len(results)
    conjecture_holds = all(rank <= D**2 * math.log(n) for D, n in zip(D_values, [random.randint(1, min(40, 2**D)) for _ in range(len(D_values))]))

    return {
        "metric_name": "minimal_rank",
        "metric_value": avg_rank,
        "instances_tested": len(results),
        "n_max": max([random.randint(1, min(40, 2**D)) for D in D_values]),
        "conjecture_holds": conjecture_holds,
        "counterexample": "" if conjecture_holds else "mapping_undefined"
    }

if __name__ == "__main__":
    import sys
    seeds = [int(s) for s in sys.argv[1:]] or [2**i + 3 for i in range(5, 30)]

    results = []
    for seed in seeds:
        result = run_trial(seed)
        print(f"TRIAL: {result}")
        results.append(result)

    avg_metric_value = sum(r["metric_value"] for r in results) / len(results)
    support_fraction = sum(1 for r in results if r["conjecture_holds"]) / len(results)

    if all(r["conjecture_holds"] for r in results):
        print(f"RESULT: SUPPORTED mean={avg_metric_value} std=0.0 support_fraction=1.0")
    elif support_fraction >= 0.8:
        print(f"RESULT: SUPPORTED mean={avg_metric_value} std=0.0 support_fraction={support_fraction}")
    else:
        first_failing_seed = next(seed for seed, result in zip(seeds, results) if not result["conjecture_holds"])
        print(f"RESULT: FALSIFIED counterexample='mapping_undefined' first_failing_seed={first_failing_seed}")
